import{_ as a,o,c as e,a0 as d}from"./chunks/framework.Bmhw_dvp.js";const _=JSON.parse('{"title":"角色分类：输出 / 辅助 / 生存（及输出子类）— Step 1–2","description":"","frontmatter":{},"headers":[],"relativePath":"llm_reco/raid-output-classification.md","filePath":"llm_reco/raid-output-classification.md"}'),r={name:"llm_reco/raid-output-classification.md"};function l(i,t,c,s,n,h){return o(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="角色分类-输出-辅助-生存-及输出子类-—-step-1–2" tabindex="-1">角色分类：输出 / 辅助 / 生存（及输出子类）— Step 1–2 <a class="header-anchor" href="#角色分类-输出-辅助-生存-及输出子类-—-step-1–2" aria-label="Permalink to &quot;角色分类：输出 / 辅助 / 生存（及输出子类）— Step 1–2&quot;">​</a></h1><blockquote><p>数据源：<code>llm_reco/char_data.json</code>（extract_chars.py 抽取自 <code>data/parsed/characters/*.json</code>，含 <code>combat</code>：连击率/行动速度sec/必杀充能%）。 机制依据：<code>game-mechanics.md</code> §1（battle.md 精确事实）。 生成脚本：<code>_classify.py</code> → <code>classification.json</code>（机器可读，供 <code>_char_score.py</code> 复用）。</p></blockquote><h2 id="_1-为什么先攻克-输出" tabindex="-1">1. 为什么先攻克&quot;输出&quot; <a class="header-anchor" href="#_1-为什么先攻克-输出" aria-label="Permalink to &quot;1. 为什么先攻克&quot;输出&quot;&quot;">​</a></h2><p>raid 木桩 BOSS 不倒下、固定防御、体力百分比流失 → <strong>站场时长固定</strong>，比拼的是&quot;单位时间总伤害&quot;。 输出角色的 kit 决定 DPS 上限；辅助/生存只决定&quot;能否把输出送上场并活够时长&quot;。故先量化输出，再谈辅助/生存占位。</p><h2 id="_2-主职三分-370-人" tabindex="-1">2. 主职三分（370 人） <a class="header-anchor" href="#_2-主职三分-370-人" aria-label="Permalink to &quot;2. 主职三分（370 人）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主职</th><th>人数</th><th>判定</th></tr></thead><tbody><tr><td>输出</td><td>289</td><td>拥有伤害型必杀（敵〇〇N倍，倍率&gt;0）</td></tr><tr><td>生存</td><td>52</td><td>治疗/免疫/不撤退/复活/减伤 为主，且无自身伤害必杀</td></tr><tr><td>辅助</td><td>23</td><td>攻buff/降防/速度/充能 为主，且无自身伤害必杀</td></tr><tr><td>其他</td><td>6</td><td>无伤害必杀、也无明显团队buff（纯功能/特殊）</td></tr></tbody></table><blockquote><p>输出角色可同时带辅助/生存标签（如 降防+不撤退）；主职只取&quot;是否有伤害必杀&quot;为分水岭。</p></blockquote><h2 id="_3-输出子类-289-人内-·-连击阈值-60" tabindex="-1">3. 输出子类（289 人内 · 连击阈值=60%） <a class="header-anchor" href="#_3-输出子类-289-人内-·-连击阈值-60" aria-label="Permalink to &quot;3. 输出子类（289 人内 · 连击阈值=60%）&quot;">​</a></h2><blockquote><p>连击率≥60% 与 必杀目标(単体/横列/全体) 为<strong>互斥桶</strong>：命中 連撃 者不计入后三者。因基础连击率只有 0/50/70 三档跳变，阈值取 60% 后仅 2 人入 連撃 桶，故 単体/横列/全体 几乎覆盖全部输出。</p></blockquote><table tabindex="0"><thead><tr><th>子类</th><th>人数</th><th>判定（battle.md 必杀倍率表 / 连击率）</th></tr></thead><tbody><tr><td>単体</td><td>106</td><td>必杀 敵単体（6→9倍，觉醒）</td></tr><tr><td>横列</td><td>55</td><td>必杀 敵横一列（前排1+后排2，4→6倍）</td></tr><tr><td>全体</td><td>126</td><td>必杀 敵全体（最多5体，2→4倍）</td></tr><tr><td>連撃</td><td>2</td><td>连击率 ≥ 60%（实战基础连击率上限70%）且含伤害必杀</td></tr></tbody></table><h3 id="_3-1-連撃-用户重点-必杀倍率权重应下调" tabindex="-1">3.1 連撃（用户重点）：必杀倍率权重应下调 <a class="header-anchor" href="#_3-1-連撃-用户重点-必杀倍率权重应下调" aria-label="Permalink to &quot;3.1 連撃（用户重点）：必杀倍率权重应下调&quot;">​</a></h3><p>battle.md 铁证：</p><ul><li>&quot;必杀充填量带来的必杀计量条增加…<strong>连击中不发生</strong>&quot; → 连击的多次攻击只充能一次（甚至不充能）。</li><li>连击使行动计量条(☆)不前进 → &quot;连击过多会使行动周期变慢，结果<strong>必杀技发动变慢</strong>&quot;。</li><li>raid 中连击不暴击、敌人不倒下 → 连击的&quot;清杂/封锁反击&quot;优点在木桩上不存在。</li></ul><p>⇒ <strong>建模结论</strong>：连击型输出角色的伤害主要来自普通攻击连击，而非必杀；其必杀释放更慢、占比更低。 在 Step5(<code>_char_score.py</code>) 评分模型中，对 連撃 实行 <strong>必杀-DPS 权重下调 + 普通攻击连击-DPS 权重上调</strong>（连续惩罚因子 <code>interval×(1+連撃率)</code>，非硬二分类）。v0.6 验证：连击率≥60% 仅 3 人（含 1 生存 バビロニア・ニル），其中 バビロニア・ニル 必杀占比仅 20.6%（普攻DPS 2622 ≫ 必杀DPS 682）。</p><h3 id="_3-2-各子类-top-代表-按必杀倍率" tabindex="-1">3.2 各子类 TOP 代表（按必杀倍率） <a class="header-anchor" href="#_3-2-各子类-top-代表-按必杀倍率" aria-label="Permalink to &quot;3.2 各子类 TOP 代表（按必杀倍率）&quot;">​</a></h3><ul><li>単体：理系のアルデバラン(×15)、閃忍マユリ(×15)、魔女カミーユ(×15)、神騎アルデバラン(×10)、黒門天(×10)</li><li>横列：ビートアクトレス・マナミ(×7)、どうぶつきぐるみ・カペラ(×6)</li><li>全体：ビートウィザード・リリアム(×9)、魔女キョウカ(×9)、ビートノーブル・サトリ(×8)</li><li>連撃：正月の切裂余命(×9, 连击70%)、体育祭のキリエル(×4, 连击70%)</li></ul><h2 id="_4-连击率分布-阈值已定-60" tabindex="-1">4. 连击率分布（阈值已定=60%） <a class="header-anchor" href="#_4-连击率分布-阈值已定-60" aria-label="Permalink to &quot;4. 连击率分布（阈值已定=60%）&quot;">​</a></h2><p>每10%一档：0–9:3 / 10–19:38 / 20–29:76 / 30–39:99 / 40–49:90 / 50–59:58 / 70–79:3。 （60–69 档为空，因基础连击率只有 0/50/70 三档跳变。）<strong>Step3 用户确认取 60%</strong> 为 連撃 阈值：命中 3 人（正月の切裂余命/体育祭のキリエル/バビロニア・ニル），其中输出 2 人、生存 1 人（バビロニア・ニル，无伤害必杀，不计入 連撃输出）。</p><h2 id="_5-下一步" tabindex="-1">5. 下一步 <a class="header-anchor" href="#_5-下一步" aria-label="Permalink to &quot;5. 下一步&quot;">​</a></h2><ul><li>Step4：固定 raid 木桩 BOSS 状态 —— <strong>已完成</strong>（R=0.50，用户确认）。</li><li>Step5：用本分类 + 連撃惩罚，重建 <code>_char_score.py</code> 的 raid 输出评分模型 —— <strong>已完成（v0.6 真实频率公式）</strong>。</li><li>其余三终局模式（B宇宙/广域战/全域战）占位，框架复用。</li></ul>',20)])])}const p=a(r,[["render",l]]);export{_ as __pageData,p as default};
